{
  "name": "Universal OSINT Orchestrator",
  "description": "An advanced intelligence system interface that simulates digital identity investigation workflows and generates Python automation code for OSINT tasks."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum TargetType {
  PHONE = 'PHONE',
  EMAIL = 'EMAIL',
  USERNAME = 'USERNAME',
  NAME = 'NAME',
  UNKNOWN = 'UNKNOWN'
}

export interface OsintResult {
  pythonCode: string;
  reportMarkdown: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  message: string;
  type: 'info' | 'success' | 'warning' | 'error' | 'system';
}

export enum AppState {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING',
  GENERATING = 'GENERATING',
  COMPLETE = 'COMPLETE',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type } from "@google/genai";
import { TargetType, OsintResult } from "../types";

const SYSTEM_PROMPT = `
ROLE: You are the Universal OSINT Orchestrator, an advanced intelligence system designed to autonomously investigate digital identities.
Your goal is to generate Python code to interface with OSINT tools and synthesize a comprehensive intelligence dossier.

CORE DIRECTIVES:
1. Polymorphism: Detect input type (Phone, Email, Username, Name).
2. Recursive Intelligence: Information found in one module seeds others.
3. Exhaustive Enumeration: Cross-reference data.

TOOLCHAIN DEFINITIONS (Simulated for Code Generation):
- Phone: PhoneInfoga, Numverify, WhatsApp-Web-Scraper, TrueCaller-Unofficial.
- Email: HaveIBeenPwned, Holehe, Hunter.io.
- Username: Maigret, Sherlock, Toutatis, SnapIntel.
- Name: TruePeopleSearch, Google Maps API.

TASK:
The user will provide a target. You must:
1. Generate the PYTHON CODE (using requests, asyncio, beautifulsoup4) that implements the PHASE 2: EXECUTION & EXPANSION workflow for the specific target. The code should be realistic, modular, and include comments explaining the "Virtual Modules" it is interfacing with.
2. Generate a HYPOTHETICAL MARKDOWN REPORT (Phase 3) simulating what the results might look like for this kind of target. Include realistic dummy data (redacted or fictionalized) to demonstrate the report structure: Executive Summary, Digital Footprint, Physical Attribution, Visual Intelligence.

OUTPUT FORMAT:
Return a JSON object with two fields:
- "pythonCode": The complete Python script.
- "reportMarkdown": The formatted Markdown report.
`;

export const generateOsintData = async (target: string, type: TargetType): Promise<OsintResult> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
      TARGET: "${target}"
      DETECTED TYPE: ${type}

      Please generate the Python investigation script and the hypothetical intelligence report.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            pythonCode: { type: Type.STRING },
            reportMarkdown: { type: Type.STRING }
          },
          required: ["pythonCode", "reportMarkdown"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response from AI");
    }

    const data = JSON.parse(text);
    return {
      pythonCode: data.pythonCode,
      reportMarkdown: data.reportMarkdown
    };

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useEffect, useRef } from 'react';
import { LogEntry } from '../types';

interface TerminalLogProps {
  logs: LogEntry[];
}

export const TerminalLog: React.FC<TerminalLogProps> = ({ logs }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  return (
    <div className="h-64 md:h-full bg-black/80 border border-osint-dim/30 rounded-lg p-4 font-mono text-xs md:text-sm overflow-hidden flex flex-col relative shadow-[0_0_15px_rgba(0,255,65,0.1)]">
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-osint-green to-transparent opacity-50"></div>
      <div className="flex-1 overflow-y-auto scrollbar-hide space-y-1">
        {logs.map((log) => (
          <div key={log.id} className="flex gap-2">
            <span className="text-gray-500 shrink-0">[{log.timestamp}]</span>
            <span className={`
              ${log.type === 'error' ? 'text-red-500' : ''}
              ${log.type === 'warning' ? 'text-yellow-500' : ''}
              ${log.type === 'success' ? 'text-osint-green font-bold' : ''}
              ${log.type === 'info' ? 'text-cyan-400' : ''}
              ${log.type === 'system' ? 'text-gray-400' : ''}
