};

import React, { useState, useEffect } from 'react';
import { Search, Globe, ShieldAlert, Cpu } from 'lucide-react';
import { TargetType, AppState } from '../types';

interface InputConsoleProps {
  onStart: (target: string, type: TargetType) => void;
  appState: AppState;
}

export const InputConsole: React.FC<InputConsoleProps> = ({ onStart, appState }) => {
  const [input, setInput] = useState('');
  const [detectedType, setDetectedType] = useState<TargetType>(TargetType.UNKNOWN);

  useEffect(() => {
    const detect = (val: string) => {
      if (!val) return TargetType.UNKNOWN;
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const phoneRegex = /^\+?[0-9\s\-\(\)]{7,}$/;
      const usernameRegex = /^@[a-zA-Z0-9_]+$/;

      if (emailRegex.test(val)) return TargetType.EMAIL;
      if (phoneRegex.test(val)) return TargetType.PHONE;
      if (usernameRegex.test(val)) return TargetType.USERNAME;
      if (val.length > 3) return TargetType.NAME; // Fallback
      return TargetType.UNKNOWN;
    };
    setDetectedType(detect(input));
  }, [input]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input && detectedType !== TargetType.UNKNOWN && appState === AppState.IDLE) {
      onStart(input, detectedType);
    }
  };

  const isLocked = appState !== AppState.IDLE;

  return (
    <div className="w-full max-w-4xl mx-auto mb-8">
      <div className="bg-osint-black border border-osint-green/30 p-1 rounded-lg shadow-[0_0_20px_rgba(0,255,65,0.15)]">
        <div className="bg-black/90 p-6 rounded relative overflow-hidden">
            {/* Background Grid Decoration */}
            <div className="absolute inset-0 scan-overlay opacity-30 pointer-events-none"></div>

            <div className="flex items-center justify-between mb-4 text-xs font-mono text-osint-dim">
                <div className="flex items-center gap-2">
                    <Globe className="w-4 h-4" />
                    <span>UNIVERSAL OSINT ORCHESTRATOR v3.0</span>
                </div>
                <div className="flex items-center gap-2">
                    <ShieldAlert className="w-4 h-4" />
                    <span>SECURE CONNECTION: ACTIVE</span>
                </div>
            </div>

            <form onSubmit={handleSubmit} className="relative z-10">
                <div className="flex flex-col md:flex-row gap-4 items-stretch">
                    <div className="flex-1 relative group">
                        <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                             <span className="text-osint-green font-mono text-lg">{'>'}</span>
                        </div>
                        <input
                            type="text"
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            disabled={isLocked}
                            className="w-full bg-gray-900/50 border border-gray-700 text-gray-100 font-mono text-lg rounded py-3 pl-10 pr-4 focus:outline-none focus:border-osint-green focus:ring-1 focus:ring-osint-green transition-all placeholder-gray-600 uppercase tracking-wider"
                            placeholder="ENTER TARGET (PHONE, EMAIL, USERNAME, NAME)"
                            spellCheck={false}
                        />
                    </div>

                    <button
                        type="submit"
                        disabled={isLocked || detectedType === TargetType.UNKNOWN}
                        className={`
                            px-8 py-3 rounded font-mono font-bold tracking-widest transition-all flex items-center justify-center gap-2
                            ${isLocked 
                                ? 'bg-gray-800 text-gray-500 cursor-not-allowed' 
                                : detectedType !== TargetType.UNKNOWN
                                    ? 'bg-osint-green text-black hover:bg-white hover:shadow-[0_0_15px_rgba(0,255,65,0.8)]'
                                    : 'bg-gray-800 text-gray-500 hover:bg-gray-700'}
                        `}
                    >
                        {isLocked ? <Cpu className="w-5 h-5 animate-spin" /> : <Search className="w-5 h-5" />}
                        {isLocked ? 'EXECUTING' : 'INITIALIZE'}
                    </button>
                </div>
            </form>

            <div className="mt-4 flex items-center gap-4 text-xs font-mono h-6">
                <span className="text-gray-500">DETECTED SELECTOR:</span>
                <span className={`px-2 py-0.5 rounded ${detectedType !== TargetType.UNKNOWN ? 'bg-osint-dim/20 text-osint-green border border-osint-dim' : 'text-gray-600'}`}>
                    {detectedType}
                </span>

                {detectedType === TargetType.PHONE && <span className="text-cyan-600 ml-auto">MODULES: PhoneInfoga, HLR Lookup</span>}
                {detectedType === TargetType.EMAIL && <span className="text-cyan-600 ml-auto">MODULES: HIBP, Holehe, Hunter</span>}
                {detectedType === TargetType.USERNAME && <span className="text-cyan-600 ml-auto">MODULES: Maigret, Sherlock</span>}
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { OsintResult } from '../types';
import ReactMarkdown from 'react-markdown';
import { Terminal, FileText, Copy, Check } from 'lucide-react';

interface ResultViewerProps {
  result: OsintResult;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ result }) => {
  const [activeTab, setActiveTab] = useState<'code' | 'report'>('code');
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(activeTab === 'code' ? result.pythonCode : result.reportMarkdown);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="w-full h-full flex flex-col bg-gray-900 border border-gray-700 rounded-lg overflow-hidden shadow-2xl">
      {/* Tab Header */}
      <div className="flex border-b border-gray-700 bg-black/40">
        <button
          onClick={() => setActiveTab('code')}
          className={`flex items-center gap-2 px-6 py-3 font-mono text-sm transition-colors ${
            activeTab === 'code' 
              ? 'bg-gray-800 text-osint-green border-t-2 border-osint-green' 
              : 'text-gray-400 hover:text-gray-200 hover:bg-gray-800/50'
          }`}
        >
          <Terminal className="w-4 h-4" />
          GENERATED_SCRIPT.PY
        </button>
        <button
          onClick={() => setActiveTab('report')}
          className={`flex items-center gap-2 px-6 py-3 font-mono text-sm transition-colors ${
            activeTab === 'report' 
              ? 'bg-gray-800 text-cyan-400 border-t-2 border-cyan-400' 
              : 'text-gray-400 hover:text-gray-200 hover:bg-gray-800/50'
          }`}
        >
          <FileText className="w-4 h-4" />
          INTELLIGENCE_DOSSIER.MD
        </button>
        <div className="ml-auto flex items-center pr-4">
            <button 
                onClick={handleCopy}
                className="flex items-center gap-2 text-xs font-mono text-gray-500 hover:text-white transition-colors"
            >
                {copied ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3" />}
                {copied ? 'COPIED' : 'COPY CONTENT'}
            </button>
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-auto bg-[#0d1117] p-6 custom-scrollbar relative">
        {activeTab === 'code' ? (
          <pre className="font-mono text-sm text-gray-300 whitespace-pre-wrap">
            <code className="language-python">{result.pythonCode}</code>
          </pre>
        ) : (
          <div className="prose prose-invert prose-green max-w-none font-sans">
             <div className="bg-red-900/20 border border-red-500/30 p-4 rounded mb-6">
                <p className="text-red-400 text-xs font-mono m-0 font-bold">
                    ⚠️ CLASSIFIED: This report contains simulated intelligence data for demonstration purposes only.
                </p>
             </div>
            <ReactMarkdown>{result.reportMarkdown}</ReactMarkdown>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useRef, useCallback } from 'react';
import { TargetType, AppState, LogEntry, OsintResult } from './types';
import { InputConsole } from './components/InputConsole';
import { TerminalLog } from './components/TerminalLog';
import { ResultViewer } from './components/ResultViewer';
import { generateOsintData } from './services/geminiService';
import { Shield, Activity, Lock, Database } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [result, setResult] = useState<OsintResult | null>(null);

  const addLog = useCallback((message: string, type: LogEntry['type'] = 'info') => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substring(7),
      timestamp: new Date().toLocaleTimeString('en-US', { hour12: false }),
      message,
      type
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const handleStart = async (target: string, type: TargetType) => {
    setAppState(AppState.ANALYZING);
    setLogs([]);
    setResult(null);

    // Initial Classification Sequence
    addLog(`INITIALIZING ORCHESTRATOR v3.0...`, 'system');
    addLog(`TARGET ACQUIRED: ${target}`, 'info');
    addLog(`SELECTOR CLASSIFICATION: ${type}`, 'success');

    try {
      // Simulate Phase 1 & 2 Workflow Visualization
      await simulateProcessing(type);

      setAppState(AppState.GENERATING);
      addLog('ESTABLISHING SECURE UPLINK TO GENERATIVE CORE...', 'system');

      // Actual Gemini API Call
      const data = await generateOsintData(target, type);

      addLog('PAYLOAD RECEIVED. DECRYPTING...', 'success');
      setResult(data);
      setAppState(AppState.COMPLETE);
      addLog('OPERATION COMPLETE. DISPLAYING INTELLIGENCE.', 'success');

    } catch (error) {
      console.error(error);
      addLog('CRITICAL FAILURE: UPLINK TERMINATED.', 'error');
      addLog(error instanceof Error ? error.message : 'Unknown error', 'error');
      setAppState(AppState.ERROR);
    } finally {
        // Reset to IDLE after a delay if error, or keep showing result if complete
        if (appState === AppState.ERROR) {
            setTimeout(() => setAppState(AppState.IDLE), 3000);
        }
    }
  };

  const simulateProcessing = async (type: TargetType) => {
    const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

    addLog('PHASE 1: INGESTION COMPLETE.', 'info');
    await delay(600);
    addLog('PHASE 2: EXECUTION & EXPANSION INITIATED...', 'warning');
    await delay(800);

    const steps = getStepsForType(type);

    for (const step of steps) {
        addLog(`> EXEC: ${step.module}`, 'system');
        await delay(Math.random() * 500 + 300);
        addLog(`  STATUS: ${step.action}...`, 'info');
        await delay(Math.random() * 500 + 300);
        if (Math.random() > 0.7) {
            addLog(`  DATA FOUND: ${step.found}`, 'success');
        }
    }

    addLog('PHASE 3: SYNTHESIS & REPORTING...', 'warning');
    await delay(800);
  };

  const getStepsForType = (type: TargetType) => {
    switch (type) {
        case TargetType.PHONE:
            return [
                { module: 'Numverify', action: 'Normalizing E.164', found: 'Carrier: VERIZON' },
                { module: 'PhoneInfoga', action: 'Running scanners', found: 'Line Type: VOIP' },
                { module: 'WhatsApp-Scraper', action: 'Extracting Profile Image', found: 'Image Hash: a7f...' },
                { module: 'ReverseImage', action: 'Cross-referencing', found: 'Social Profile Match' },
            ];
        case TargetType.EMAIL:
             return [
                { module: 'HaveIBeenPwned', action: 'Querying Breach Database', found: 'Breaches: 12' },
                { module: 'Holehe', action: 'Enumerating Accounts', found: 'Registered: Instagram, Spotify' },
                { module: 'Hunter.io', action: 'Verifying Corporate Status', found: 'Professional Domain' },
            ];
        case TargetType.USERNAME:
            return [
                { module: 'Maigret', action: 'Deep Web Scan (500+ Sites)', found: 'Profile: GitHub' },
                { module: 'Sherlock', action: 'Checking Social Media', found: 'Profile: Twitter' },
                { module: 'Toutatis', action: 'Extracting Instagram Bio', found: 'Email: hidden***@gmail.com' },
            ];
        case TargetType.NAME:
            return [
                { module: 'TruePeopleSearch', action: 'Scraping Public Records', found: 'Address History: 3' },
                { module: 'Google Maps API', action: 'Geocoding locations', found: 'Coordinates Lat/Lon' },
                { module: 'Graph', action: 'Mapping Relations', found: 'Potential Relatives: 2' },
            ];
        default:
            return [];
    }
  };

  return (
    <div className="min-h-screen bg-black text-gray-200 font-sans selection:bg-osint-green selection:text-black flex flex-col">
      {/* Header */}
      <header className="border-b border-gray-800 bg-black/50 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
            <div className="flex items-center gap-3">
                <Shield className="w-6 h-6 text-osint-green" />
                <h1 className="text-xl font-bold font-mono tracking-tighter text-white">
                    OSINT<span className="text-osint-green">ORCHESTRATOR</span>
                </h1>
            </div>
            <div className="flex items-center gap-6 text-xs font-mono text-gray-500">
                <div className="flex items-center gap-2">
                    <Activity className={`w-3 h-3 ${appState === AppState.ANALYZING ? 'text-osint-green animate-pulse' : ''}`} />
                    <span>SYSTEM: {appState === AppState.IDLE ? 'READY' : 'BUSY'}</span>
                </div>
                <div className="flex items-center gap-2">
                    <Database className="w-3 h-3" />
                    <span>MODULES: 14</span>
                </div>
                <div className="flex items-center gap-2">
                    <Lock className="w-3 h-3 text-osint-green" />
                    <span>OPSEC: ENFORCED</span>
                </div>
            </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl w-full mx-auto p-4 md:p-8 flex flex-col">

        <InputConsole onStart={handleStart} appState={appState} />

        {/* Workspace Grid */}
        <div className="flex-1 grid grid-cols-1 lg:grid-cols-3 gap-6 min-h-[500px]">
            {/* Left: Live Terminal Log */}
            <div className="lg:col-span-1 h-full flex flex-col">
                <div className="mb-2 flex items-center justify-between text-xs font-mono text-gray-500 uppercase tracking-widest">
                    <span>Execution Log</span>
                    <span className="text-osint-dim">Live Feed</span>
                </div>
                <TerminalLog logs={logs} />
            </div>

            {/* Right: Results / Visualization */}
            <div className="lg:col-span-2 h-full flex flex-col">
                <div className="mb-2 flex items-center justify-between text-xs font-mono text-gray-500 uppercase tracking-widest">
                    <span>Intelligence Output</span>
                    {appState === AppState.COMPLETE && <span className="text-osint-green">Decrypted</span>}
                </div>

                {result ? (
                    <ResultViewer result={result} />
                ) : (
                    <div className="flex-1 bg-gray-900/30 border border-gray-800 rounded-lg flex items-center justify-center relative overflow-hidden">
                        {appState !== AppState.IDLE && (
                           <div className="absolute inset-0 bg-[url('https://assets.codepen.io/13471/sparkle.gif')] opacity-5 mix-blend-screen pointer-events-none"></div>
                        )}
                        <div className="text-center p-8">
                            {appState === AppState.IDLE && (
                                <>
                                    <Shield className="w-16 h-16 text-gray-800 mx-auto mb-4" />
                                    <p className="text-gray-600 font-mono text-sm">AWAITING TARGET INPUT</p>
                                    <p className="text-gray-700 text-xs mt-2 max-w-sm mx-auto">
                                        Enter a selector above to begin autonomous investigation.
                                        All actions are simulated for demonstration purposes.
                                    </p>
                                </>
                            )}
                            {(appState === AppState.ANALYZING || appState === AppState.GENERATING) && (
                                <>
                                     <div className="w-16 h-16 border-4 border-osint-dim/30 border-t-osint-green rounded-full animate-spin mx-auto mb-6"></div>
                                     <p className="text-osint-green font-mono animate-pulse">
                                        {appState === AppState.ANALYZING ? 'EXECUTING MODULES...' : 'SYNTHESIZING DOSSIER...'}
                                     </p>
                                </>
                            )}
                        </div>
                    </div>
                )}
            </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="border-t border-gray-900 bg-black py-6">
        <div className="max-w-7xl mx-auto px-4 text-center">
            <p className="text-gray-600 text-xs font-mono">
                UNIVERSAL OSINT ORCHESTRATOR // EDUCATIONAL PURPOSES ONLY // DO NOT USE FOR ILLEGAL ACTIVITIES
            </p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { TargetType, OsintResult } from "../types";

const SYSTEM_PROMPT = `
ROLE: You are the Universal OSINT Orchestrator, a real-time intelligence gathering interface.
Your goal is to perform an INITIAL RECONNAISSANCE scan on the target using Google Search and then generate a Python script for deeper, automated investigation.

CORE DIRECTIVES:
1. **REAL DATA ONLY**: Do NOT generate fake, simulated, or dummy data. Use the Google Search tool to find *actual* public footprints (social media, news, registries).
2. **HONESTY**: If Google Search returns no relevant results for the specific target, explicitly state: "No publicly available intelligence found for this selector."
3. **REPORTING**: Synthesize found data into a clean, professional Markdown dossier. Cite sources/URLs where possible.
4. **AUTOMATION**: Generate a valid, working Python script that a security researcher could run to perform a deeper dive (using libraries like requests, beautifulsoup4, etc.).

TASK:
The user will provide a target. You must:
1. Search Google for the target to find real-world traces.
2. Compile the "reportMarkdown" based EXCLUSIVELY on search results or general knowledge (e.g., if it's a known entity).
3. Write the "pythonCode" to automate further checks for this specific target type.

OUTPUT FORMAT:
Return a JSON object with two fields:
- "pythonCode": The complete Python script.
- "reportMarkdown": The intelligence dossier (Markdown format).
`;

export const generateOsintData = async (target: string, type: TargetType): Promise<OsintResult> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
      TARGET: "${target}"
      DETECTED TYPE: ${type}

      Conduct real-time OSINT reconnaissance and generate the automation script.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            pythonCode: { type: Type.STRING },
            reportMarkdown: { type: Type.STRING }
          },
          required: ["pythonCode", "reportMarkdown"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response from AI");
    }

    const data = JSON.parse(text);
    return {
      pythonCode: data.pythonCode,
      reportMarkdown: data.reportMarkdown
    };

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useState, useRef, useCallback } from 'react';
import { TargetType, AppState, LogEntry, OsintResult } from './types';
import { InputConsole } from './components/InputConsole';
import { TerminalLog } from './components/TerminalLog';
import { ResultViewer } from './components/ResultViewer';
import { generateOsintData } from './services/geminiService';
import { Shield, Activity, Lock, Database } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [result, setResult] = useState<OsintResult | null>(null);

  const addLog = useCallback((message: string, type: LogEntry['type'] = 'info') => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substring(7),
      timestamp: new Date().toLocaleTimeString('en-US', { hour12: false }),
      message,
      type
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const handleStart = async (target: string, type: TargetType) => {
    setAppState(AppState.ANALYZING);
    setLogs([]);
    setResult(null);

    // Initial Classification Sequence
    addLog(`INITIALIZING ORCHESTRATOR v3.0...`, 'system');
    addLog(`TARGET ACQUIRED: ${target}`, 'info');
    addLog(`SELECTOR CLASSIFICATION: ${type}`, 'success');

    try {
      // Show progress logs (No fake data)
      await runProgressSequence(type);

      setAppState(AppState.GENERATING);
      addLog('ESTABLISHING SECURE UPLINK TO INTELLIGENCE CORE...', 'system');

      // Actual Gemini API Call with Search Grounding
      const data = await generateOsintData(target, type);

      addLog('PAYLOAD RECEIVED. DECRYPTING...', 'success');
      setResult(data);
      setAppState(AppState.COMPLETE);
      addLog('OPERATION COMPLETE. DISPLAYING REAL-TIME INTELLIGENCE.', 'success');

    } catch (error) {
      console.error(error);
      addLog('CRITICAL FAILURE: UPLINK TERMINATED.', 'error');
      addLog(error instanceof Error ? error.message : 'Unknown error', 'error');
      setAppState(AppState.ERROR);
    } finally {
        if (appState === AppState.ERROR) {
            setTimeout(() => setAppState(AppState.IDLE), 3000);
        }
    }
  };

  const runProgressSequence = async (type: TargetType) => {
    const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

    addLog('PHASE 1: INGESTION COMPLETE.', 'info');
    await delay(600);
    addLog('PHASE 2: REAL-TIME RECONNAISSANCE INITIATED...', 'warning');
    await delay(800);

    const steps = [
        "Initializing public registry scanners...",
        "Querying global search indices...",
        "Analyzing digital footprint patterns...",
        "Cross-referencing available social data...",
        "Synthesizing intelligence dossier..."
    ];

    for (const step of steps) {
        addLog(`> EXEC: ${step}`, 'system');
        await delay(Math.random() * 600 + 400);
    }

    addLog('PHASE 3: COMPILING DATA...', 'warning');
    await delay(500);
  };

  return (
    <div className="min-h-screen bg-black text-gray-200 font-sans selection:bg-osint-green selection:text-black flex flex-col">
      {/* Header */}
      <header className="border-b border-gray-800 bg-black/50 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
            <div className="flex items-center gap-3">
                <Shield className="w-6 h-6 text-osint-green" />
                <h1 className="text-xl font-bold font-mono tracking-tighter text-white">
                    OSINT<span className="text-osint-green">ORCHESTRATOR</span>
                </h1>
            </div>
            <div className="flex items-center gap-6 text-xs font-mono text-gray-500">
                <div className="flex items-center gap-2">
                    <Activity className={`w-3 h-3 ${appState === AppState.ANALYZING ? 'text-osint-green animate-pulse' : ''}`} />
                    <span>SYSTEM: {appState === AppState.IDLE ? 'READY' : 'BUSY'}</span>
                </div>
                <div className="flex items-center gap-2">
                    <Database className="w-3 h-3" />
                    <span>LIVE CONNECT</span>
                </div>
                <div className="flex items-center gap-2">
                    <Lock className="w-3 h-3 text-osint-green" />
                    <span>OPSEC: ENFORCED</span>
                </div>
            </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl w-full mx-auto p-4 md:p-8 flex flex-col">

        <InputConsole onStart={handleStart} appState={appState} />

        {/* Workspace Grid */}
        <div className="flex-1 grid grid-cols-1 lg:grid-cols-3 gap-6 min-h-[500px]">
            {/* Left: Live Terminal Log */}
            <div className="lg:col-span-1 h-full flex flex-col">
                <div className="mb-2 flex items-center justify-between text-xs font-mono text-gray-500 uppercase tracking-widest">
                    <span>Execution Log</span>
                    <span className="text-osint-dim">Live Feed</span>
                </div>
                <TerminalLog logs={logs} />
            </div>

            {/* Right: Results / Visualization */}
            <div className="lg:col-span-2 h-full flex flex-col">
                <div className="mb-2 flex items-center justify-between text-xs font-mono text-gray-500 uppercase tracking-widest">
                    <span>Intelligence Output</span>
                    {appState === AppState.COMPLETE && <span className="text-osint-green">Active</span>}
                </div>

                {result ? (
                    <ResultViewer result={result} />
                ) : (
                    <div className="flex-1 bg-gray-900/30 border border-gray-800 rounded-lg flex items-center justify-center relative overflow-hidden">
                        {appState !== AppState.IDLE && (
                           <div className="absolute inset-0 bg-[url('https://assets.codepen.io/13471/sparkle.gif')] opacity-5 mix-blend-screen pointer-events-none"></div>
                        )}
                        <div className="text-center p-8">
                            {appState === AppState.IDLE && (
                                <>
                                    <Shield className="w-16 h-16 text-gray-800 mx-auto mb-4" />
                                    <p className="text-gray-600 font-mono text-sm">AWAITING TARGET INPUT</p>
                                    <p className="text-gray-700 text-xs mt-2 max-w-sm mx-auto">
                                        Enter a selector above to initiate real-time reconnaissance.
                                    </p>
                                </>
                            )}
                            {(appState === AppState.ANALYZING || appState === AppState.GENERATING) && (
                                <>
                                     <div className="w-16 h-16 border-4 border-osint-dim/30 border-t-osint-green rounded-full animate-spin mx-auto mb-6"></div>
                                     <p className="text-osint-green font-mono animate-pulse">
                                        {appState === AppState.ANALYZING ? 'GATHERING INTELLIGENCE...' : 'COMPILING DOSSIER...'}
                                     </p>
                                </>
                            )}
                        </div>
                    </div>
                )}
            </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="border-t border-gray-900 bg-black py-6">
        <div className="max-w-7xl mx-auto px-4 text-center">
            <p className="text-gray-600 text-xs font-mono">
                UNIVERSAL OSINT ORCHESTRATOR // EDUCATIONAL PURPOSES ONLY // DO NOT USE FOR ILLEGAL ACTIVITIES
            </p>
        </div>
      </footer>
