const SYSTEM_PROMPT = `
ROLE: You are the Universal OSINT Orchestrator, a dedicated Data Extraction Engine.
Your goal is to perform a FORENSIC-LEVEL SCRAPE of information on the target using Google Search.

CORE DIRECTIVES:
1. **NO OMISSIONS**: You must extract and report EVERY specific data point found. Do NOT summarize or generalize.
   - **Numerical Data**: Preserves ALL scores (CGPA, GPA, Test Scores), IDs, Dates, Phone Numbers, Prices.
   - **Textual Data**: Preserve full job titles, specific project names, exact quotes from bios.
2. **REAL DATA ONLY**: Do NOT generate fake, simulated, or dummy data.
3. **SCOPE**: Exhaustively search:
   - **Education/Work**: Resumes, CVs, Portfolios, University results, Dean's lists, Corporate directories.
   - **Development**: GitHub, GitLab, StackOverflow, Dev.to, NPM, PyPI.
   - **Communication**: Discord, Telegram, Matrix (public channels/logs).
   - **Social**: LinkedIn, X (Twitter), Facebook, Instagram, Reddit.
4. **HONESTY**: If no data is found, state it.
5. **PUBLIC DATA**: All information found via the Google Search tool is considered public record. Do not censor public academic or professional metrics.

TASK:
The user will provide a target and potentially "Additional Context". You must:
1. Search Google for the target using the context to narrow down results.
2. Extract *granular* details. If a resume or profile is found, extract every listed skill, score (CGPA/GPA), and date.
3. STREAM the output as a professional Markdown dossier.

OUTPUT FORMAT:
Stream raw Markdown directly.
`;

export const streamOsintData = async (
    target: string, 
    type: TargetType, 
    additionalInfo: string, 
    onUpdate: (chunk: string) => void,
    customApiKey?: string
): Promise<void> => {
  try {
    const apiKey = customApiKey || process.env.API_KEY;

    if (!apiKey) {
        throw new Error("No API Configuration Found. Please set a Custom API Key.");
    }

    const ai = new GoogleGenAI({ apiKey });
    const timestamp = new Date().toISOString();

    let contextPrompt = "";
    if (additionalInfo) {
        contextPrompt = `\nADDITIONAL CONTEXT PROVIDED BY INTELLIGENCE OFFICER:\n"${additionalInfo}"\nUse this context to filter false positives and find the correct individual.\n`;
    }

    const prompt = `
      TARGET: "${target}"
      DETECTED TYPE: ${type}
      TIMESTAMP: ${timestamp}
      ${contextPrompt}

      Conduct a deep, multi-pass OSINT reconnaissance. 
      1. Search for social media profiles, developer accounts, and public records.
      2. **Search specifically for resumes, CVs, portfolios, and academic records (CGPA, Grades, University).**
      3. Extract ALL numerical data found (dates, scores, IDs) verbatim.
      4. Do not abbreviate findings. List all potential digital footprints.

      Begin streaming the Markdown report immediately.
    `;

    // Use generateContentStream for real-time output
    const responseStream = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview', 
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        tools: [{ googleSearch: {} }],
        // Extreme determinism to prevent missing data on re-runs
        temperature: 0,
        topK: 1, 
        topP: 0.1,
      }
    });

    for await (const chunk of responseStream) {
        const text = chunk.text;
        if (text) {
            onUpdate(text);
        }
    }

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

