                                        <ChevronDown className="w-3 h-3" />
                                    </div>
                                    <span className="group-hover:tracking-widest transition-all duration-300">CONTEXT PARAMETERS (OPTIONAL)</span>
                                </button>

                                <div className={`transition-all duration-500 ease-in-out overflow-hidden ${isExpanded ? 'max-h-48 opacity-100' : 'max-h-0 opacity-0'}`}>
                                    <textarea
                                        value={additionalInfo}
                                        onChange={(e) => setAdditionalInfo(e.target.value)}
                                        disabled={isLocked}
                                        placeholder="PROVIDE ADDITIONAL CONTEXT TO REDUCE FALSE POSITIVES (e.g. 'Software Engineer in London', 'Attended MIT', 'Works at Google')..."
                                        className="w-full bg-gray-900/30 border border-gray-800 text-gray-300 font-mono text-sm rounded p-4 focus:outline-none focus:border-osint-green/50 focus:ring-1 focus:ring-osint-green/50 transition-all h-24 resize-none placeholder-gray-600 backdrop-blur-sm"
                                    />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback } from 'react';
