import React, { useState, useEffect } from 'react';
import { Search, Globe, ShieldAlert, Cpu, ChevronDown, ChevronUp, PlusCircle, Scan } from 'lucide-react';
import { TargetType, AppState } from '../types';

interface InputConsoleProps {
  onStart: (target: string, type: TargetType, additionalInfo: string) => void;
  appState: AppState;
  initialInput?: string;
  initialInfo?: string;
  autoExpand?: boolean;
}

export const InputConsole: React.FC<InputConsoleProps> = ({ 
    onStart, 
    appState, 
    initialInput = '', 
    initialInfo = '',
    autoExpand = false 
}) => {
  const [input, setInput] = useState(initialInput);
  const [additionalInfo, setAdditionalInfo] = useState(initialInfo);
  const [isExpanded, setIsExpanded] = useState(autoExpand);
  const [detectedType, setDetectedType] = useState<TargetType>(TargetType.UNKNOWN);
  const [hasTyped, setHasTyped] = useState(false);

  useEffect(() => {
    setInput(initialInput);
    if (initialInput) setHasTyped(true);
  }, [initialInput]);

  useEffect(() => {
    setAdditionalInfo(initialInfo);
  }, [initialInfo]);

  useEffect(() => {
    if (autoExpand) setIsExpanded(true);
  }, [autoExpand]);

  useEffect(() => {
    if (input.length > 0) {
        setHasTyped(true);
    } else {
        setHasTyped(false);
    }

    const detect = (val: string) => {
      if (!val) return TargetType.UNKNOWN;
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const phoneRegex = /^\+?[0-9\s\-\(\)]{7,}$/;
      const usernameRegex = /^@[a-zA-Z0-9_]+$/;

      if (emailRegex.test(val)) return TargetType.EMAIL;
      if (phoneRegex.test(val)) return TargetType.PHONE;
      if (usernameRegex.test(val)) return TargetType.USERNAME;
      if (val.length > 3) return TargetType.NAME; // Fallback
      return TargetType.UNKNOWN;
    };
    setDetectedType(detect(input));
  }, [input]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input && detectedType !== TargetType.UNKNOWN && !isLocked) {
      onStart(input, detectedType, additionalInfo);
    }
  };

  const isLocked = appState === AppState.ANALYZING || appState === AppState.GENERATING;
  const isIdle = appState === AppState.IDLE;

  return (
    <div className={`w-full max-w-4xl mx-auto transition-all duration-700 ease-in-out ${isIdle ? 'scale-105' : 'scale-100'}`} id="input-console">
      <div className={`bg-osint-black border transition-all duration-500 ${hasTyped ? 'border-osint-green/50 shadow-[0_0_30px_rgba(0,255,65,0.15)]' : 'border-gray-800 shadow-none'} p-1 rounded-lg`}>
        <div className="bg-black/90 p-6 rounded relative overflow-hidden transition-all duration-500">
            {/* Background Grid Decoration */}
            <div className={`absolute inset-0 scan-overlay pointer-events-none transition-opacity duration-1000 ${hasTyped ? 'opacity-30' : 'opacity-10'}`}></div>

            <div className="flex items-center justify-between mb-8 text-xs font-mono text-osint-dim transition-opacity duration-500">
                <div className="flex items-center gap-2">
                    <Globe className="w-4 h-4" />
                    <span className="tracking-widest">UNIVERSAL OSINT ORCHESTRATOR v3.5</span>
                </div>
                <div className={`flex items-center gap-2 transition-opacity duration-500 ${hasTyped ? 'opacity-100' : 'opacity-0'}`}>
                    <ShieldAlert className="w-4 h-4" />
                    <span>SECURE UPLINK: READY</span>
                </div>
            </div>

            <form onSubmit={handleSubmit} className="relative z-10">
                <div className="flex flex-col gap-6">
                    {/* Main Input Area */}
                    <div className="relative group">
                        <div className={`absolute top-1/2 -translate-y-1/2 left-4 transition-all duration-500 ${hasTyped ? 'text-osint-green scale-100' : 'text-gray-600 scale-90'}`}>
                            {hasTyped ? <span className="font-mono text-xl">{'>'}</span> : <Scan className="w-5 h-5" />}
                        </div>
                        <input
                            type="text"
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            disabled={isLocked}
                            className={`
                                w-full bg-gray-900/30 border text-gray-100 font-mono text-xl rounded py-4 pl-12 pr-4 
                                focus:outline-none focus:ring-1 transition-all duration-500
                                ${hasTyped ? 'border-gray-700 focus:border-osint-green focus:ring-osint-green' : 'border-transparent focus:border-gray-700 focus:ring-gray-700'}
                                placeholder-gray-700 uppercase tracking-wider
                            `}
                            placeholder="ENTER TARGET SELECTOR..."
                            spellCheck={false}
                        />

                        {/* Detected Type Tag - Animates In */}
                        <div className={`
                            absolute top-1/2 -translate-y-1/2 right-4 pointer-events-none
                            transition-all duration-700 ease-out
                            ${hasTyped && detectedType !== TargetType.UNKNOWN ? 'opacity-100 translate-x-0' : 'opacity-0 translate-x-4'}
                        `}>
                             <span className="px-3 py-1 rounded bg-osint-dim/20 text-osint-green border border-osint-dim text-xs font-mono tracking-widest shadow-[0_0_10px_rgba(0,255,65,0.2)]">
                                {detectedType} DETECTED
                            </span>
                        </div>
                    </div>

                    {/* Controls & Context - Collapsible */}
                    <div className={`
                        grid transition-all duration-700 ease-in-out overflow-hidden
                        ${hasTyped ? 'grid-rows-[1fr] opacity-100 mt-2' : 'grid-rows-[0fr] opacity-0 mt-0'}
                    `}>
                        <div className="min-h-0 flex flex-col gap-4">

                            {/* Context Parameters */}
                            <div className="border-t border-gray-800/50 pt-4 animate-in fade-in slide-in-from-top-4 duration-700 delay-100 fill-mode-backwards">
                                <button 
                                    type="button"
                                    onClick={() => setIsExpanded(!isExpanded)}
                                    className="flex items-center gap-2 text-xs font-mono text-gray-500 hover:text-osint-green transition-colors mb-3 group"
                                >
                                    <div className={`transition-transform duration-300 ${isExpanded ? 'rotate-180' : 'rotate-0'}`}>
                                        <ChevronDown className="w-3 h-3" />
                                    </div>
                                    <span className="group-hover:tracking-widest transition-all duration-300">CONTEXT PARAMETERS (OPTIONAL)</span>
                                </button>

                                <div className={`transition-all duration-500 ease-in-out overflow-hidden ${isExpanded ? 'max-h-48 opacity-100' : 'max-h-0 opacity-0'}`}>
                                    <textarea
                                        value={additionalInfo}
                                        onChange={(e) => setAdditionalInfo(e.target.value)}
                                        disabled={isLocked}
                                        placeholder="PROVIDE ADDITIONAL CONTEXT TO REDUCE FALSE POSITIVES (e.g. 'Software Engineer in London', 'Attended MIT', 'Works at Google')..."
                                        className="w-full bg-gray-900/30 border border-gray-800 text-gray-300 font-mono text-sm rounded p-4 focus:outline-none focus:border-osint-green/50 focus:ring-1 focus:ring-osint-green/50 transition-all h-24 resize-none placeholder-gray-600 backdrop-blur-sm"
                                    />
                                </div>
                            </div>

                            <div className="flex justify-end">
                                <button
                                    type="submit"
                                    disabled={isLocked || detectedType === TargetType.UNKNOWN}
                                    className={`
                                        px-10 py-3 rounded font-mono font-bold tracking-[0.2em] transition-all duration-300 flex items-center justify-center gap-3 uppercase
                                        ${isLocked || detectedType === TargetType.UNKNOWN
                                            ? 'bg-gray-800 text-gray-500 cursor-not-allowed' 
                                            : 'bg-osint-green text-black hover:bg-white hover:shadow-[0_0_20px_rgba(0,255,65,0.6)] transform hover:-translate-y-1'}
                                    `}
                                >
                                    {isLocked ? <Cpu className="w-5 h-5 animate-spin" /> : <Search className="w-5 h-5" />}
                                    {isLocked ? 'EXECUTING' : 'INITIALIZE SCAN'}
                                </button>
                            </div>

                        </div>
                    </div>
                </div>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { OsintResult } from '../types';
import ReactMarkdown from 'react-markdown';
