  onRetry: () => void;
  onRefine: () => void;
  isStreaming: boolean;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ result, onRetry, onRefine, isStreaming }) => {
  const [copied, setCopied] = useState(false);
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isStreaming && bottomRef.current) {
        bottomRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [result.reportMarkdown, isStreaming]);

  const handleCopy = () => {
    navigator.clipboard.writeText(result.reportMarkdown);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // Check if we are streaming but have no text yet
  const isThinking = isStreaming && !result.reportMarkdown;

  return (
    <div className="w-full h-full flex flex-col bg-osint-black border border-osint-green/30 rounded-lg overflow-hidden shadow-[0_0_30px_rgba(0,255,65,0.05)] relative group">
