      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-2 border-r-2 border-osint-green z-20"></div>

      {/* Tab Header */}
      <div className="flex flex-wrap gap-2 border-b border-gray-800 bg-black/60 backdrop-blur-sm z-10 p-2 items-center shrink-0">
        <div
          className="flex items-center gap-2 px-4 py-2 font-mono text-xs md:text-sm tracking-wider transition-all bg-osint-green/10 text-osint-green border-r border-osint-green/30"
        >
          <FileText className="w-4 h-4" />
          INTELLIGENCE_DOSSIER
          {isStreaming && <span className="w-2 h-2 bg-osint-green rounded-full animate-pulse ml-2"></span>}
        </div>

        <div className="ml-auto flex items-center gap-3 pr-2">
            {!isStreaming && (
                <>
                    <button 
                        onClick={onRetry}
                        className="flex items-center gap-1.5 text-xs font-mono text-gray-400 hover:text-white transition-colors uppercase border border-gray-800 hover:border-gray-600 px-2 py-1 rounded bg-gray-900"
                        title="Retry with same parameters"
                    >
                        <RefreshCw className="w-3 h-3" />
                        RETRY
                    </button>
                    <button 
                        onClick={onRefine}
                        className="flex items-center gap-1.5 text-xs font-mono text-gray-400 hover:text-osint-green transition-colors uppercase border border-gray-800 hover:border-osint-green/50 px-2 py-1 rounded bg-gray-900"
                        title="Edit parameters and retry"
                    >
                        <Edit className="w-3 h-3" />
                        REFINE
                    </button>
                    <div className="h-4 w-[1px] bg-gray-800 mx-1"></div>
                </>
            )}

