import React, { useState, useCallback } from 'react';
import { TargetType, AppState, LogEntry, OsintResult } from './types';
import { InputConsole } from './components/InputConsole';
import { TerminalLog } from './components/TerminalLog';
import { ResultViewer } from './components/ResultViewer';
import { ApiKeyModal } from './components/ApiKeyModal';
import { DisclaimerOverlay } from './components/DisclaimerOverlay';
import { streamOsintData } from './services/geminiService';
import { Shield, Activity, Database, Key, AlertTriangle } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [result, setResult] = useState<OsintResult | null>(null);

  // Disclaimer State
  const [showDisclaimer, setShowDisclaimer] = useState(false);
  const [disclaimerTimer, setDisclaimerTimer] = useState<ReturnType<typeof setTimeout> | null>(null);

  // State for Retry Logic
  const [lastTarget, setLastTarget] = useState<string>('');
  const [lastType, setLastType] = useState<TargetType>(TargetType.UNKNOWN);
  const [lastInfo, setLastInfo] = useState<string>('');
  const [expandInput, setExpandInput] = useState(false);

  // API Key Management
  const [customApiKey, setCustomApiKey] = useState<string>('');
  const [isKeyModalOpen, setIsKeyModalOpen] = useState(false);
  const [isErrorMode, setIsErrorMode] = useState(false);

  const addLog = useCallback((message: string, type: LogEntry['type'] = 'info') => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substring(7),
      timestamp: new Date().toLocaleTimeString('en-US', { hour12: false }),
      message,
      type
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const handleStart = async (target: string, type: TargetType, additionalInfo: string) => {
    // Reset States
    setAppState(AppState.ANALYZING);
    setLogs([]);
    setResult(null); 
    setLastTarget(target);
    setLastType(type);
    setLastInfo(additionalInfo);
    setExpandInput(false);
    setShowDisclaimer(false);

    // Initial Classification Sequence
    addLog(`INITIALIZING ORCHESTRATOR v3.5...`, 'system');
    addLog(`TARGET ACQUIRED: ${target}`, 'info');
    if (additionalInfo) addLog(`CONTEXT PARAMETERS LOADED.`, 'info');
    addLog(`SELECTOR CLASSIFICATION: ${type}`, 'success');

    // Start Disclaimer Timer (5 seconds)
    const timer = setTimeout(() => {
        setShowDisclaimer(true);
    }, 5000);
    setDisclaimerTimer(timer);

    try {
      await runProgressSequence(type);

      setAppState(AppState.GENERATING);
      addLog('ESTABLISHING SECURE UPLINK TO INTELLIGENCE CORE...', 'system');

      if (customApiKey) {
        addLog('USING CUSTOM ENCRYPTION KEY (USER PROVIDED)', 'info');
      }

      // Initialize empty result for streaming
      setResult({ reportMarkdown: '' });
      addLog('INCOMING DATA STREAM DETECTED...', 'success');

      // Use a local variable to capture the stream in the closure
      let streamBuffer = '';

      // Streaming Call
      await streamOsintData(
          target, 
          type, 
          additionalInfo, 
          (chunk) => {
             streamBuffer += chunk;
             setResult({ reportMarkdown: streamBuffer });
          },
          customApiKey
      );

      setAppState(AppState.COMPLETE);
      addLog('DATA STREAM COMPLETE. DOSSIER COMPILED.', 'success');

    } catch (error) {
      console.error(error);
      addLog('CRITICAL FAILURE: UPLINK TERMINATED.', 'error');
      addLog(error instanceof Error ? error.message : 'Unknown error', 'error');
      setAppState(AppState.ERROR);

      setIsErrorMode(true);
      setIsKeyModalOpen(true);
      if (disclaimerTimer) clearTimeout(disclaimerTimer);
    } 
  };

  const runProgressSequence = async (type: TargetType) => {
    const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

    addLog('PHASE 1: INGESTION COMPLETE.', 'info');
    await delay(1500);
    addLog('PHASE 2: REAL-TIME RECONNAISSANCE INITIATED...', 'warning');
    await delay(2000);

    const steps = [
        "Initializing deep-web registry scanners...",
        "Querying global search indices (Google, Bing)...",
        "Analyzing developer footprints (GitHub, GitLab)...",
        "Enumerating communication channels...",
        "Synthesizing intelligence dossier..."
    ];

    // Significantly increased delays to simulate "Deep Thinking"
    for (const step of steps) {
        addLog(`> EXEC: ${step}`, 'system');
        // Random delay between 2.5s and 4.0s
        await delay(Math.random() * 1500 + 2500);
    }
  };

  const handleSaveKey = (key: string) => {
    setCustomApiKey(key);
    setIsKeyModalOpen(false);
    setIsErrorMode(false);
    if (key) {
        addLog('CUSTOM API KEY CONFIGURED.', 'success');
    }
  };

  const handleRetry = () => {
    if (lastTarget) {
        handleStart(lastTarget, lastType, lastInfo);
    }
  };

  const handleRefine = () => {
    setExpandInput(true);
    const element = document.getElementById('input-console');
    if (element) {
        element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const handleDisclaimerAcknowledge = () => {
    setShowDisclaimer(false);
  };

  return (
    <div className="min-h-screen bg-black text-gray-200 font-sans selection:bg-osint-green selection:text-black flex flex-col overflow-hidden">
      <ApiKeyModal 
        isOpen={isKeyModalOpen} 
        onClose={() => setIsKeyModalOpen(false)} 
        onSave={handleSaveKey}
        initialValue={customApiKey}
        isErrorMode={isErrorMode}
      />

      {/* Header */}
      <header className="border-b border-gray-800 bg-black/50 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
            <div className="flex items-center gap-3">
                <Shield className="w-6 h-6 text-osint-green" />
                <h1 className="text-xl font-bold font-mono tracking-tighter text-white">
                    OSINT<span className="text-osint-green">ORCHESTRATOR</span>
                </h1>
            </div>
            <div className="flex items-center gap-6 text-xs font-mono text-gray-500">
                <div className="hidden md:flex items-center gap-2">
                    <Activity className={`w-3 h-3 ${appState === AppState.ANALYZING || appState === AppState.GENERATING ? 'text-osint-green animate-pulse' : ''}`} />
                    <span>SYSTEM: {appState === AppState.IDLE ? 'READY' : 'BUSY'}</span>
                </div>
                <div className="hidden md:flex items-center gap-2">
                    <Database className="w-3 h-3" />
                    <span>LIVE CONNECT</span>
                </div>
                <button 
                    onClick={() => { setIsErrorMode(false); setIsKeyModalOpen(true); }}
                    className={`flex items-center gap-2 px-3 py-1 rounded border transition-colors ${customApiKey ? 'border-osint-green text-osint-green bg-osint-green/10' : 'border-gray-700 hover:border-gray-500'}`}
                >
                    <Key className="w-3 h-3" />
                    <span>{customApiKey ? 'KEY: ACTIVE' : 'SET API KEY'}</span>
                </button>
            </div>
        </div>
      </header>

      {/* Main Content with Hero Transitions */}
      <main className="flex-1 max-w-7xl w-full mx-auto p-4 md:p-8 flex flex-col relative">

        {/* Input Section - Hero Mode Logic */}
        <div className={`
            flex flex-col transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)]
            ${appState === AppState.IDLE ? 'flex-grow justify-center py-20' : 'flex-none pt-0 pb-8'}
        `}>
            <InputConsole 
                onStart={handleStart} 
                appState={appState} 
                initialInput={lastTarget}
                initialInfo={lastInfo}
                autoExpand={expandInput}
            />
        </div>

        {/* Workspace Grid - Fades in/up when active */}
        <div className={`
            flex-1 grid grid-cols-1 lg:grid-cols-3 gap-6 min-h-[500px] transition-all duration-1000 delay-300
            ${appState === AppState.IDLE ? 'opacity-0 translate-y-20 h-0 hidden' : 'opacity-100 translate-y-0 h-auto'}
        `}>
            {/* Left: Live Terminal Log */}
            <div className="lg:col-span-1 h-full flex flex-col">
                <div className="mb-2 flex items-center justify-between text-xs font-mono text-gray-500 uppercase tracking-widest">
                    <span>Execution Log</span>
                    <span className="text-osint-dim">Live Feed</span>
                </div>
                <TerminalLog logs={logs} />
            </div>

            {/* Right: Results / Visualization */}
            <div className="lg:col-span-2 h-full flex flex-col relative">
                <div className="mb-2 flex items-center justify-between text-xs font-mono text-gray-500 uppercase tracking-widest">
                    <span>Intelligence Output</span>
                    {appState === AppState.COMPLETE && <span className="text-osint-green">Active</span>}
                    {appState === AppState.GENERATING && <span className="text-osint-green animate-pulse">Streaming...</span>}
                </div>

                {/* Result Container with Overlay Logic */}
                <div className="relative flex-1 rounded-lg overflow-hidden">
                    {/* Disclaimer Overlay (Timer Triggered) */}
                    {showDisclaimer && (
                        <DisclaimerOverlay onAcknowledge={handleDisclaimerAcknowledge} />
                    )}

                    {result ? (
                        <ResultViewer 
                            result={result} 
                            onRetry={handleRetry}
                            onRefine={handleRefine}
                            isStreaming={appState === AppState.GENERATING}
                        />
                    ) : (
                        <div className="h-full bg-gray-900/30 border border-gray-800 rounded-lg flex items-center justify-center relative overflow-hidden">
                            {appState !== AppState.IDLE && appState !== AppState.ERROR && (
                            <div className="absolute inset-0 bg-[url('https://assets.codepen.io/13471/sparkle.gif')] opacity-5 mix-blend-screen pointer-events-none"></div>
                            )}
                            <div className="text-center p-8">
                                {(appState === AppState.ANALYZING) && (
                                    <>
                                        <div className="w-16 h-16 border-4 border-osint-dim/30 border-t-osint-green rounded-full animate-spin mx-auto mb-6"></div>
                                        <p className="text-osint-green font-mono animate-pulse tracking-widest">
                                            AWAITING NEURAL HANDSHAKE...
                                        </p>
                                    </>
                                )}
                                {appState === AppState.ERROR && (
                                    <>
                                        <AlertTriangle className="w-16 h-16 text-red-500 mx-auto mb-6" />
                                        <p className="text-red-500 font-mono font-bold">CONNECTION TERMINATED</p>
                                        <p className="text-gray-500 text-xs mt-2">Check logs for details.</p>
                                        <button onClick={() => setAppState(AppState.IDLE)} className="mt-4 text-xs text-gray-400 hover:text-white underline">RESET SYSTEM</button>
                                    </>
                                )}
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="border-t border-gray-900 bg-black py-6">
        <div className="max-w-7xl mx-auto px-4 flex flex-col md:flex-row items-center justify-between gap-4">
            <p className="text-gray-600 text-xs font-mono text-center md:text-left">
                UNIVERSAL OSINT ORCHESTRATOR // EDUCATIONAL PURPOSES ONLY
            </p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Search, Globe, ShieldAlert, Cpu, ChevronDown, Scan } from 'lucide-react';
import { TargetType, AppState } from '../types';

interface InputConsoleProps {
  onStart: (target: string, type: TargetType, additionalInfo: string) => void;
  appState: AppState;
  initialInput?: string;
  initialInfo?: string;
  autoExpand?: boolean;
}

export const InputConsole: React.FC<InputConsoleProps> = ({ 
    onStart, 
    appState, 
    initialInput = '', 
    initialInfo = '',
    autoExpand = false 
}) => {
  const [input, setInput] = useState(initialInput);
  const [additionalInfo, setAdditionalInfo] = useState(initialInfo);
  const [isExpanded, setIsExpanded] = useState(autoExpand);
  const [detectedType, setDetectedType] = useState<TargetType>(TargetType.UNKNOWN);
  const [hasTyped, setHasTyped] = useState(false);

  useEffect(() => {
    setInput(initialInput);
    if (initialInput) setHasTyped(true);
  }, [initialInput]);

  useEffect(() => {
    setAdditionalInfo(initialInfo);
  }, [initialInfo]);

  useEffect(() => {
    if (autoExpand) setIsExpanded(true);
  }, [autoExpand]);

  useEffect(() => {
    if (input.length > 0) {
        setHasTyped(true);
    } else {
        setHasTyped(false);
    }

    const detect = (val: string) => {
      if (!val) return TargetType.UNKNOWN;
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const phoneRegex = /^\+?[0-9\s\-\(\)]{7,}$/;
      const usernameRegex = /^@[a-zA-Z0-9_]+$/;

      if (emailRegex.test(val)) return TargetType.EMAIL;
      if (phoneRegex.test(val)) return TargetType.PHONE;
      if (usernameRegex.test(val)) return TargetType.USERNAME;
      if (val.length > 3) return TargetType.NAME; // Fallback
      return TargetType.UNKNOWN;
    };
    setDetectedType(detect(input));
  }, [input]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input && detectedType !== TargetType.UNKNOWN && !isLocked) {
      onStart(input, detectedType, additionalInfo);
    }
  };

  const isLocked = appState === AppState.ANALYZING || appState === AppState.GENERATING;
  const isIdle = appState === AppState.IDLE;

  return (
    <div className={`w-full max-w-4xl mx-auto transition-all duration-700 ease-in-out ${isIdle ? 'scale-100 md:scale-105' : 'scale-100'}`} id="input-console">
      <div className={`bg-osint-black border transition-all duration-500 ${hasTyped ? 'border-osint-green/50 shadow-[0_0_30px_rgba(0,255,65,0.15)]' : 'border-gray-800 shadow-none'} p-0.5 md:p-1 rounded-lg`}>
        <div className="bg-black/90 p-4 md:p-6 rounded relative overflow-hidden transition-all duration-500">
            {/* Background Grid Decoration */}
            <div className={`absolute inset-0 scan-overlay pointer-events-none transition-opacity duration-1000 ${hasTyped ? 'opacity-30' : 'opacity-10'}`}></div>

            <div className="flex items-center justify-between mb-6 md:mb-8 text-[10px] md:text-xs font-mono text-osint-dim transition-opacity duration-500">
                <div className="flex items-center gap-2">
                    <Globe className="w-3 h-3 md:w-4 md:h-4" />
                    <span className="tracking-widest hidden sm:inline">UNIVERSAL OSINT ORCHESTRATOR v3.5</span>
                    <span className="tracking-widest sm:hidden">OSINT ORCHESTRATOR v3.5</span>
                </div>
                <div className={`flex items-center gap-2 transition-opacity duration-500 ${hasTyped ? 'opacity-100' : 'opacity-0'}`}>
                    <ShieldAlert className="w-3 h-3 md:w-4 md:h-4" />
                    <span className="hidden sm:inline">SECURE UPLINK: READY</span>
                    <span className="sm:hidden">READY</span>
                </div>
            </div>

            <form onSubmit={handleSubmit} className="relative z-10">
                <div className="flex flex-col gap-4 md:gap-6">
                    {/* Main Input Area */}
                    <div className="relative group">
                        <div className={`absolute top-1/2 -translate-y-1/2 left-3 md:left-4 transition-all duration-500 ${hasTyped ? 'text-osint-green scale-100' : 'text-gray-600 scale-90'}`}>
                            {hasTyped ? <span className="font-mono text-lg md:text-xl">{'>'}</span> : <Scan className="w-4 h-4 md:w-5 md:h-5" />}
                        </div>
                        <input
                            type="text"
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            disabled={isLocked}
                            className={`
                                w-full bg-gray-900/30 border text-gray-100 font-mono text-lg md:text-xl rounded py-3 md:py-4 pl-10 md:pl-12 pr-20 md:pr-32 
                                focus:outline-none focus:ring-1 transition-all duration-500
                                ${hasTyped ? 'border-gray-700 focus:border-osint-green focus:ring-osint-green' : 'border-transparent focus:border-gray-700 focus:ring-gray-700'}
                                placeholder-gray-700 uppercase tracking-wider
                            `}
                            placeholder="ENTER TARGET..."
                            spellCheck={false}
                        />

                        {/* Detected Type Tag - Animates In */}
                        <div className={`
                            absolute top-1/2 -translate-y-1/2 right-2 md:right-4 pointer-events-none
                            transition-all duration-700 ease-out
                            ${hasTyped && detectedType !== TargetType.UNKNOWN ? 'opacity-100 translate-x-0' : 'opacity-0 translate-x-4'}
                        `}>
                             <span className="px-2 py-0.5 md:px-3 md:py-1 rounded bg-osint-dim/20 text-osint-green border border-osint-dim text-[10px] md:text-xs font-mono tracking-widest shadow-[0_0_10px_rgba(0,255,65,0.2)]">
                                {detectedType}
                            </span>
                        </div>
                    </div>

                    {/* Controls & Context - Collapsible */}
                    <div className={`
                        grid transition-all duration-700 ease-in-out overflow-hidden
                        ${hasTyped ? 'grid-rows-[1fr] opacity-100 mt-0 md:mt-2' : 'grid-rows-[0fr] opacity-0 mt-0'}
                    `}>
                        <div className="min-h-0 flex flex-col gap-4">

                            {/* Context Parameters */}
                            <div className="border-t border-gray-800/50 pt-3 md:pt-4 animate-in fade-in slide-in-from-top-4 duration-700 delay-100 fill-mode-backwards">
                                <button 
                                    type="button"
                                    onClick={() => setIsExpanded(!isExpanded)}
                                    className="flex items-center gap-2 text-[10px] md:text-xs font-mono text-gray-500 hover:text-osint-green transition-colors mb-2 group w-full md:w-auto"
                                >
                                    <div className={`transition-transform duration-300 ${isExpanded ? 'rotate-180' : 'rotate-0'}`}>
                                        <ChevronDown className="w-3 h-3" />
                                    </div>
                                    <span className="group-hover:tracking-widest transition-all duration-300">CONTEXT PARAMETERS (OPTIONAL)</span>
                                </button>

                                <div className={`transition-all duration-500 ease-in-out overflow-hidden ${isExpanded ? 'max-h-48 opacity-100' : 'max-h-0 opacity-0'}`}>
                                    <textarea
                                        value={additionalInfo}
                                        onChange={(e) => setAdditionalInfo(e.target.value)}
                                        disabled={isLocked}
                                        placeholder="PROVIDE ADDITIONAL CONTEXT (e.g. 'Software Engineer in London')..."
                                        className="w-full bg-gray-900/30 border border-gray-800 text-gray-300 font-mono text-xs md:text-sm rounded p-3 focus:outline-none focus:border-osint-green/50 focus:ring-1 focus:ring-osint-green/50 transition-all h-20 md:h-24 resize-none placeholder-gray-600 backdrop-blur-sm"
                                    />
                                </div>
                            </div>

                            <div className="flex justify-end">
                                <button
                                    type="submit"
                                    disabled={isLocked || detectedType === TargetType.UNKNOWN}
                                    className={`
                                        w-full md:w-auto px-6 md:px-10 py-3 rounded font-mono font-bold tracking-[0.2em] transition-all duration-300 flex items-center justify-center gap-3 uppercase text-xs md:text-base
                                        ${isLocked || detectedType === TargetType.UNKNOWN
                                            ? 'bg-gray-800 text-gray-500 cursor-not-allowed' 
                                            : 'bg-osint-green text-black hover:bg-white hover:shadow-[0_0_20px_rgba(0,255,65,0.6)] transform hover:-translate-y-1'}
                                    `}
                                >
                                    {isLocked ? <Cpu className="w-4 h-4 md:w-5 md:h-5 animate-spin" /> : <Search className="w-4 h-4 md:w-5 md:h-5" />}
                                    {isLocked ? 'EXECUTING' : 'INITIALIZE SCAN'}
                                </button>
                            </div>

                        </div>
                    </div>
                </div>
            </form>
        </div>
      </div>
    </div>
  );
};

