interface ResultViewerProps {
  result: OsintResult;
  onRetry: () => void;
  onRefine: () => void;
  isStreaming: boolean;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ result, onRetry, onRefine, isStreaming }) => {
  const [copied, setCopied] = useState(false);
