          <span className="hidden sm:inline">INTELLIGENCE_DOSSIER</span>
          <span className="sm:hidden">DOSSIER</span>
          {isStreaming && <span className="w-1.5 h-1.5 md:w-2 md:h-2 bg-osint-green rounded-full animate-pulse ml-2"></span>}
