import { GoogleGenAI } from "@google/genai";
import { TargetType } from "../types";

const SYSTEM_PROMPT = `
ROLE: You are the Universal OSINT Orchestrator.
GOAL: Perform a FORENSIC-LEVEL SCRAPE. 

CORE DIRECTIVES:
1. **ZERO TRUNCATION**: You are prohibited from summarizing. If you find a list of 50 items, LIST ALL 50.
2. **VERBOSITY**: Prefer long, detailed reports over concise ones. 
3. **REAL DATA ONLY**: Do NOT generate fake data.
4. **SCOPE**:
   - **Education/Work**: Extract specific dates, GPA, project names, and thesis titles.
   - **Development**: Extract repository names, commit history summaries, and languages used.
   - **Social**: Extract bio text exactly as written.

TASK:
1. Search Google for the target using the context.
2. If multiple potential matches are found, list the top 3 most likely candidates with reasoning.
3. STREAM the output as a detailed Markdown dossier.

OUTPUT RULES:
- **Do not** use phrases like "various projects" or "and others". List them.
- **Do not** cut off long text. 
- **Do not** omit dates or locations.
- **IMPORTANT**: Do NOT wrap the output in a markdown code block (e.g., \`\`\`markdown). Return RAW markdown text only.
`;

export const streamOsintData = async (
    target: string, 
    type: TargetType, 
    additionalInfo: string, 
    onUpdate: (chunk: string) => void,
    customApiKey?: string
): Promise<void> => {
  try {
    const apiKey = customApiKey || process.env.API_KEY;

    if (!apiKey) {
        throw new Error("No API Configuration Found. Please set a Custom API Key.");
    }

    const ai = new GoogleGenAI({ apiKey });
    const timestamp = new Date().toISOString();

    let contextPrompt = "";
    if (additionalInfo) {
        contextPrompt = `\nADDITIONAL CONTEXT PROVIDED BY INTELLIGENCE OFFICER:\n"${additionalInfo}"\nUse this context to filter false positives and find the correct individual.\n`;
    }

    const prompt = `
      TARGET: "${target}"
      DETECTED TYPE: ${type}
      TIMESTAMP: ${timestamp}
      ${contextPrompt}

      Conduct a deep, multi-pass OSINT reconnaissance. 
      **Search specifically for resumes, CVs, portfolios, and academic records.**

      CRITICAL INSTRUCTION:
      Provide the MOST DETAILED report possible. 
      If you find a GitHub profile, list the top repositories. 
      If you find a LinkedIn, list the full work history with dates.
      DO NOT TRIM THE OUTPUT.

      Begin streaming the Markdown report immediately.
    `;

    // Switch to gemini-3-pro-preview for maximum reasoning capability and detail
    const responseStream = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview', 
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_PROMPT,
        tools: [{ googleSearch: {} }],
        temperature: 0, 
      }
    });

    for await (const chunk of responseStream) {
        const text = chunk.text;
        if (text) {
            onUpdate(text);
        }
    }

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { OsintResult } from '../types';
import ReactMarkdown from 'react-markdown';
import { FileText, Copy, Check, RefreshCw, Edit, Terminal, Server } from 'lucide-react';

interface ResultViewerProps {
  result: OsintResult;
  onRetry: () => void;
  onRefine: () => void;
  isStreaming: boolean;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ result, onRetry, onRefine, isStreaming }) => {
  const [copied, setCopied] = useState(false);
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isStreaming && bottomRef.current) {
        bottomRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [result.reportMarkdown, isStreaming]);

  const handleCopy = () => {
    navigator.clipboard.writeText(result.reportMarkdown);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // Cleaning function to strip code blocks if the model hallucinates them
  const cleanMarkdown = (text: string) => {
    if (!text) return '';
    // Removes ```markdown at the start, ``` at the start/end
    return text
        .replace(/^```markdown\s*/i, '') // Remove start
        .replace(/^```\s*/, '')          // Remove generic start
        .replace(/```\s*$/, '');         // Remove end
  };

  // Check if we are streaming but have no text yet (The long wait)
  const isThinking = isStreaming && !result.reportMarkdown;

  return (
    <div className="w-full h-full flex flex-col bg-osint-black border border-osint-green/30 rounded-lg overflow-hidden shadow-[0_0_30px_rgba(0,255,65,0.05)] relative group">
      {/* Decorative Border Lines */}
      <div className="absolute top-0 left-0 w-6 h-6 md:w-8 md:h-8 border-t-2 border-l-2 border-osint-green z-20"></div>
      <div className="absolute bottom-0 right-0 w-6 h-6 md:w-8 md:h-8 border-b-2 border-r-2 border-osint-green z-20"></div>

      {/* Tab Header */}
      <div className="flex flex-wrap gap-2 border-b border-gray-800 bg-black/60 backdrop-blur-sm z-10 p-2 items-center shrink-0">
        <div
          className="flex items-center gap-2 px-2 md:px-4 py-1.5 md:py-2 font-mono text-[10px] md:text-sm tracking-wider transition-all bg-osint-green/10 text-osint-green border-r border-osint-green/30"
        >
          <FileText className="w-3 h-3 md:w-4 md:h-4" />
          <span className="hidden sm:inline">INTELLIGENCE_DOSSIER</span>
          <span className="sm:hidden">DOSSIER</span>
          {isStreaming && <span className="w-1.5 h-1.5 md:w-2 md:h-2 bg-osint-green rounded-full animate-pulse ml-2"></span>}
        </div>

        <div className="ml-auto flex items-center gap-2 md:gap-3 pr-2">
            {!isStreaming && (
                <>
                    <button 
                        onClick={onRetry}
                        className="flex items-center gap-1 text-[10px] md:text-xs font-mono text-gray-400 hover:text-white transition-colors uppercase border border-gray-800 hover:border-gray-600 px-2 py-1 rounded bg-gray-900"
                        title="Retry"
                    >
                        <RefreshCw className="w-3 h-3" />
                        <span className="hidden sm:inline">RETRY</span>
                    </button>
                    <button 
                        onClick={onRefine}
                        className="flex items-center gap-1 text-[10px] md:text-xs font-mono text-gray-400 hover:text-osint-green transition-colors uppercase border border-gray-800 hover:border-osint-green/50 px-2 py-1 rounded bg-gray-900"
                        title="Refine"
                    >
                        <Edit className="w-3 h-3" />
                        <span className="hidden sm:inline">REFINE</span>
                    </button>
                    <div className="h-4 w-[1px] bg-gray-800 mx-1"></div>
                </>
            )}

            <button 
                onClick={handleCopy}
                className="flex items-center gap-2 text-[10px] md:text-xs font-mono text-osint-dim hover:text-osint-green transition-colors uppercase tracking-widest"
            >
                {copied ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                <span className="hidden sm:inline">{copied ? 'COPIED' : 'COPY'}</span>
            </button>
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-auto bg-[#050505] p-4 md:p-6 custom-scrollbar relative">
        <div className="absolute inset-0 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] z-0 pointer-events-none bg-[length:100%_4px,3px_100%]"></div>

        <div className="relative z-10 h-full">
            {isThinking ? (
                 <div className="h-full flex flex-col items-center justify-center space-y-4 opacity-80">
                    <div className="flex items-center gap-2 text-osint-green font-mono text-xs md:text-sm animate-pulse">
                        <Server className="w-4 h-4 md:w-5 md:h-5" />
                        <span>AWAITING GEMINI API RESPONSE...</span>
                    </div>
                    {/* Progress Bar Animation tuned to ~60s */}
                    <div className="w-48 md:w-72 h-1 bg-gray-900 rounded-full overflow-hidden border border-gray-800">
                        <div className="h-full bg-osint-green animate-[width_60s_ease-out_forwards] w-0 transition-all"></div>
                    </div>
