            <p className="text-gray-600 text-[10px] md:text-xs font-mono text-center md:text-left">
                UNIVERSAL OSINT ORCHESTRATOR // EDUCATIONAL PURPOSES ONLY
            </p>
        </div>
      </footer>
    </div>
  );
};

export default App;

