export const checkModelAvailability = async (apiKey: string, modelId: string): Promise<string> => {
  if (!apiKey) throw new Error("API Key is required");

  try {
    const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${apiKey}`,
        "HTTP-Referer": window.location.href,
        "X-Title": "Universal OSINT Orchestrator",
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        model: modelId,
        messages: [{ role: "user", content: "ping" }],
        max_tokens: 1
      })
    });

    if (!response.ok) {
        const err = await response.json();
        throw new Error(err.error?.message || `Status ${response.status}`);
    }

    return modelId;
  } catch (e: any) {
    throw new Error(`Connection Failed: ${e.message}`);
  }
};

export const streamOsintData = async (
    target: string, 
    type: TargetType, 
    additionalInfo: string, 
    onUpdate: (chunk: string) => void,
    customApiKey?: string,
    modelId: string = 'google/gemini-2.0-flash-lite-preview-02-05:free'
): Promise<void> => {
  // Priority: 
  // 1. Custom Key entered in UI
  // 2. API_KEY (Bridged via vite.config.ts define)
  const apiKey = customApiKey || process.env.API_KEY;

  if (!apiKey) {
      throw new Error("No API Key Found. Please set a Custom API Key or configure API_KEY.");
  }

  const timestamp = new Date().toISOString();

  let contextPrompt = "";
  if (additionalInfo) {
      contextPrompt = `\nADDITIONAL CONTEXT PROVIDED BY INTELLIGENCE OFFICER:\n"${additionalInfo}"\nUse this context to filter false positives and find the correct individual.\n`;
  }

  const userPrompt = `
    TARGET: "${target}"
    DETECTED TYPE: ${type}
    TIMESTAMP: ${timestamp}
    ${contextPrompt}

    Conduct a deep, multi-pass OSINT reconnaissance. 
    **Search specifically for resumes, CVs, portfolios, and academic records.**

    CRITICAL INSTRUCTION:
    Provide the MOST DETAILED report possible. 
    If you find a GitHub profile, list the top repositories. 
    If you find a LinkedIn, list the full work history with dates.
    DO NOT TRIM THE OUTPUT.

    Begin streaming the Markdown report immediately.
  `;

  try {
    const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
        method: "POST",
        headers: {
            "Authorization": `Bearer ${apiKey}`,
            "HTTP-Referer": window.location.href,
            "X-Title": "Universal OSINT Orchestrator",
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            model: modelId,
            messages: [
                { role: "system", content: SYSTEM_PROMPT },
                { role: "user", content: userPrompt }
            ],
            stream: true
        })
    });

    if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error?.message || `OpenRouter API Error: ${response.status}`);
    }

    const reader = response.body?.getReader();
    const decoder = new TextDecoder("utf-8");

    if (!reader) throw new Error("Response body is null");

    while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value);
        const lines = chunk.split("\n").filter(line => line.trim() !== "");

        for (const line of lines) {
            if (line.includes("[DONE]")) return;

            if (line.startsWith("data: ")) {
                try {
                    const json = JSON.parse(line.replace("data: ", ""));
                    const content = json.choices[0]?.delta?.content;
                    if (content) {
                        onUpdate(content);
                    }
                } catch (e) {
                    console.warn("Error parsing chunk", e);
                }
            }
        }
    }

  } catch (error: any) {
    console.error("OpenRouter API Error:", error);
    throw error;
  }
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { TargetType, AppState, LogEntry, OsintResult } from './types';
import { InputConsole } from './components/InputConsole';
import { TerminalLog } from './components/TerminalLog';
import { ResultViewer } from './components/ResultViewer';
import { ApiKeyModal } from './components/ApiKeyModal';
import { DisclaimerOverlay } from './components/DisclaimerOverlay';
import { streamOsintData, FREE_MODELS } from './services/geminiService';
import { Shield, Activity, Database, Key, AlertTriangle, Cpu } from 'lucide-react';

const STORAGE_KEY = 'osint_openrouter_api_key';
const STORAGE_MODEL_KEY = 'osint_openrouter_model_id';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [result, setResult] = useState<OsintResult | null>(null);

  // Disclaimer State
  const [showDisclaimer, setShowDisclaimer] = useState(false);

  // State for Retry Logic
  const [lastTarget, setLastTarget] = useState<string>('');
  const [lastType, setLastType] = useState<TargetType>(TargetType.UNKNOWN);
  const [lastInfo, setLastInfo] = useState<string>('');
  const [expandInput, setExpandInput] = useState(false);

  // API Key & Model Management
  const [customApiKey, setCustomApiKey] = useState<string>('');
  const [selectedModel, setSelectedModel] = useState<string>(FREE_MODELS[0].id);
  const [isKeyModalOpen, setIsKeyModalOpen] = useState(false);
  const [isErrorMode, setIsErrorMode] = useState(false);

  // Refs for cancellation
  const abortControllerRef = useRef<AbortController | null>(null);

  // Initialize: Check for stored API Key and Model
  useEffect(() => {
    const storedKey = localStorage.getItem(STORAGE_KEY);
    const storedModel = localStorage.getItem(STORAGE_MODEL_KEY);

    // Check if we have a default environment key
    const hasDefaultKey = process.env.API_KEY;

    if (storedKey) {
        setCustomApiKey(storedKey);
    }

    if (storedModel) {
        setSelectedModel(storedModel);
    }

    // Only open modal automatically if we have NO key source at all
    if (!storedKey && !hasDefaultKey) {
        setIsKeyModalOpen(true);
    }
  }, []);

  const addLog = useCallback((message: string, type: LogEntry['type'] = 'info') => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substring(7),
      timestamp: new Date().toLocaleTimeString('en-US', { hour12: false }),
      message,
      type
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const handleStart = (target: string, type: TargetType, additionalInfo: string) => {
    // 1. Set Initial Data
    setLastTarget(target);
    setLastType(type);
    setLastInfo(additionalInfo);
    setExpandInput(false);

    // 2. Clear previous results explicitly to reset container height
    setResult(null);
    setLogs([]);

    // 3. Reveal the UI by transitioning state from IDLE
    // This unhides the result container where the disclaimer lives
    setAppState(AppState.ANALYZING);

    // 4. Show Disclaimer Immediately
    setShowDisclaimer(true);
  };

  const handleDisclaimerAcknowledge = () => {
    setShowDisclaimer(false);
    startScan(lastTarget, lastType, lastInfo);
  };

  const startScan = async (target: string, type: TargetType, additionalInfo: string) => {
    // Ensure state is ANALYZING
    setAppState(AppState.ANALYZING);

    // Initialize AbortController for this run
    abortControllerRef.current = new AbortController();

    try {
        // Start the visual log sequence (Runs in background)
        const logPromise = runRealisticSequence();

        // Start the actual API call
        // Initialize empty result for streaming
        setResult({ reportMarkdown: '' });

        let streamBuffer = '';

        // Wait for the API
        await streamOsintData(
            target, 
            type, 
            additionalInfo, 
            (chunk) => {
                // When first chunk arrives, update state to GENERATING
                if (streamBuffer === '') {
                    setAppState(AppState.GENERATING);
                }
                streamBuffer += chunk;
                setResult({ reportMarkdown: streamBuffer });
            },
            customApiKey, // If empty, service uses env var
            selectedModel
        );

        await logPromise;

        setAppState(AppState.COMPLETE);
        addLog('Response stream closed successfully.', 'success');

    } catch (error) {
        console.error(error);
        const errMsg = error instanceof Error ? error.message : 'Unknown error';

        addLog('API REQUEST FAILED.', 'error');
        addLog(errMsg, 'error');
        setAppState(AppState.ERROR);

        if (errMsg.includes("Key") || errMsg.includes("Auth") || errMsg.includes("401")) {
             setIsErrorMode(true);
             setIsKeyModalOpen(true);
        }
    }
  };

  const runRealisticSequence = async () => {
    const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

    addLog(`Initializing OpenRouter client...`, 'system');
    await delay(500);

    addLog(`Target: "${lastTarget}" (${lastType})`, 'info');
    if (lastInfo) addLog(`Injecting context parameters...`, 'info');

    await delay(1000);
    const modelName = FREE_MODELS.find(m => m.id === selectedModel)?.name || 'Unknown Model';
    addLog(`Constructing prompt for '${modelName}'...`, 'system');
    await delay(1000);

    addLog(`Dispatching payload to OpenRouter Neural Network...`, 'warning');
    await delay(1000); 

    // OpenRouter is usually faster than Gemini with tools, but we keep some suspense
    addLog(`Resolving model node routing...`, 'info');
    await delay(1000); 

    addLog(`Streaming started. Decrypting packets...`, 'success');
  };

  const handleSaveKey = (key: string, shouldSave: boolean, modelId: string) => {
    setCustomApiKey(key);
    setSelectedModel(modelId);

    if (shouldSave && key) {
        localStorage.setItem(STORAGE_KEY, key);
    } else {
        localStorage.removeItem(STORAGE_KEY);
    }

    if (modelId) {
        localStorage.setItem(STORAGE_MODEL_KEY, modelId);
    }

    if (key || process.env.API_KEY) {
         addLog(`Secure Uplink Established. Model: ${modelId}.`, 'success');
    }

    setIsKeyModalOpen(false);
    setIsErrorMode(false);
  };

  const handleRetry = () => {
    if (lastTarget) {
        handleStart(lastTarget, lastType, lastInfo);
    }
  };

  const handleRefine = () => {
    setExpandInput(true);
    const element = document.getElementById('input-console');
    if (element) {
        element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  // Check if we have an active key source (Env or Custom)
  const hasActiveKey = !!(customApiKey || process.env.API_KEY);

  return (
    <div className="min-h-screen bg-black text-gray-200 font-sans selection:bg-osint-green selection:text-black flex flex-col overflow-x-hidden">
      <ApiKeyModal 
