  isErrorMode?: boolean;
}

export const ApiKeyModal: React.FC<ApiKeyModalProps> = ({ isOpen, onClose, onSave, initialValue = '', isErrorMode = false }) => {
  const [key, setKey] = useState(initialValue);
  const [shouldSave, setShouldSave] = useState(false);
