                    <span>Gemini API Key</span>
                    <span className="text-gray-500 text-[10px]">Leave empty to use default</span>
                </label>
                <input 
                    type="password" 
                    value={key}
                    onChange={(e) => {
                        setKey(e.target.value);
                        setValidationError(null); 
                    }}
