  const [copied, setCopied] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const bottomRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isStreaming && bottomRef.current) {
        bottomRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [result.reportMarkdown, isStreaming]);

  const handleCopy = () => {
    navigator.clipboard.writeText(result.reportMarkdown);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownloadPdf = async () => {
    if (!contentRef.current || isExporting) return;
    setIsExporting(true);

    // @ts-ignore
    const html2pdf = window.html2pdf;

    if (!html2pdf) {
        console.error("html2pdf library not loaded");
        setIsExporting(false);
        return;
    }

    // 1. Create a dedicated container for the export
    // We position it 'fixed' so it's relative to the viewport (crucial for html2canvas)
    // but put it behind everything.
    const container = document.createElement('div');
    container.id = 'osint-pdf-container';
    Object.assign(container.style, {
        position: 'fixed',
        left: '0',
        top: '0',
        width: '210mm', // A4 Width
