        color: '#e0e0e0', // Force light text
        fontFamily: '"JetBrains Mono", monospace',
        padding: '15mm',
        boxSizing: 'border-box'
    });

    // 2. Clone content and clean styling
    const clone = contentRef.current.cloneNode(true) as HTMLElement;

    // Remove scroll/height constraints from the clone so it expands fully
    clone.style.height = 'auto';
    clone.style.width = '100%';
    clone.style.overflow = 'visible';
    clone.style.maxHeight = 'none';

    // Clean specific tailwind classes that might conflict
    clone.classList.remove('h-full', 'overflow-auto', 'min-h-full', 'animate-blur-in');

    // Add a custom header for the PDF
    const header = document.createElement('div');
    header.innerHTML = `
      <div style="border-bottom: 1px solid #00ff41; padding-bottom: 10px; margin-bottom: 20px; display: flex; justify-content: space-between; align-items: center;">
        <h1 style="color: #00ff41; font-size: 18px; margin: 0; font-family: 'JetBrains Mono', monospace;">OSINT INTELLIGENCE DOSSIER</h1>
        <span style="color: #008F11; font-size: 10px; font-family: 'JetBrains Mono', monospace;">CONFIDENTIAL // GENERATED REPORT</span>
      </div>
    `;

    container.appendChild(header);
    container.appendChild(clone);
    document.body.appendChild(container);

    // 3. Wait for DOM to paint (CRITICAL for avoiding blank pages)
    await new Promise(resolve => setTimeout(resolve, 500));

    // 4. Configure PDF Options
    const opt = {
        margin: 0, 
        filename: `OSINT_DOSSIER_${new Date().toISOString().slice(0, 10)}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        enableLinks: true,
        html2canvas: { 
            scale: 2, 
            useCORS: true, 
            backgroundColor: '#050505', // Ensure canvas background is dark
            logging: false,
            windowWidth: 1000 // Simulate desktop width to prevent mobile layout shifts
        },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };

    // 5. Generate and Cleanup
    try {
        await html2pdf().set(opt).from(container).save();
    } catch (err) {
        console.error("PDF Export failed", err);
    } finally {
        if (document.body.contains(container)) {
            document.body.removeChild(container);
        }
        setIsExporting(false);
    }
  };

  // Cleaning function to strip code blocks if the model hallucinates them
  const cleanMarkdown = (text: string) => {
    if (!text) return '';
    return text
        .replace(/^```markdown\s*/i, '')
        .replace(/^```\s*/, '')
        .replace(/```\s*$/, '');
  };

  const isThinking = isStreaming && !result.reportMarkdown;

  return (
    <div className="w-full h-full flex flex-col bg-osint-black border border-osint-green/30 rounded-lg overflow-hidden shadow-[0_0_30px_rgba(0,255,65,0.05)] relative group animate-blur-in origin-center">
