                        title="Download PDF"
                    >
                        {isExporting ? <Loader2 className="w-3 h-3 animate-spin" /> : <Download className="w-3 h-3" />}
                        <span className="hidden sm:inline">PDF</span>
                    </button>

                    <div className="h-4 w-[1px] bg-gray-800 mx-1"></div>
                </>
            )}

            <button 
