            margin: 0,
            filename: `OSINT_REPORT_${new Date().getTime()}.pdf`,
            image: { type: 'jpeg', quality: 0.98 },
            enableLinks: true,
            html2canvas: { 
                scale: 2, 
                useCORS: true, 
                backgroundColor: '#0a0a0a',
                logging: false
            },
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
        };

        await html2pdf().set(options).from(printContainer).save();

        // 7. Cleanup
        document.body.removeChild(printContainer);

    } catch (error) {
        console.error("PDF Generation failed:", error);
    } finally {
        setIsExporting(false);
    }
  };

  // Cleaning function to strip code blocks if the model hallucinates them
  const cleanMarkdown = (text: string) => {
    if (!text) return '';
    return text
        .replace(/^```markdown\s*/i, '')
        .replace(/^```\s*/, '')
        .replace(/```\s*$/, '');
  };

  const isThinking = isStreaming && !result.reportMarkdown;

